const b = $json.body ?? $json;
const channel = b.channel;
const senderId = channel === 'widget' ? b.sessionId : b.from;   // whatsapp → from
if (!channel || !senderId) throw new Error('normalize: missing channel/senderId'); // fail-loud
const message_id = b.messageId || b.message_id || null;
return [{ json: { channel, senderId, sender_key: `${channel}:${senderId}`, text: b.text, message_id } }];

