const cfg = $('Load Config').first().json.config;
const j = $json;
const stored = (j.state && j.state.slots) || {};   // Merge State'ten saklı slotlar
const fresh  = j.slots || {};                       // Validate Intent'ten bu turun LLM slotları
let serviceId = fresh.serviceId ?? stored.serviceId ?? null;
// Codex root-cause: serviceId MUST be a real config service — drop anything the LLM invents so it never
// reaches the booking path (Slot Gate then re-asks). Also keeps the event key on a known ASCII set.
if (serviceId && !(cfg.services || []).some(sv => sv.id === serviceId)) serviceId = null;
const merged = {
  serviceId,
  date:      fresh.date      ?? stored.date      ?? null,
  time:      fresh.time      ?? stored.time      ?? null
};
return [{ json: { ...j, state: { ...j.state, slots: merged } } }];

// Slot Gate — deterministik: required {service, date, time} tam mı? stage + next_ask hesapla.
const j = $json;
const cfg = $('Load Config').first().json.config;
const s = (j.state && j.state.slots) || {};
const hasService = !!s.serviceId && (cfg.services || []).some(sv => sv.id === s.serviceId); // enforce config allow-list (Codex root-cause: an invented serviceId must NOT count as filled)
const hasDate    = !!s.date && DateTime.fromISO(s.date).isValid; // NIT-3: reject a pattern-valid-but-fake date (e.g. 2026-02-30) here -> stays collecting + re-asks, never hits freeBusy (wrong 503)
const hasTime    = !!s.time;

let next_ask = null;
if (!hasService)               next_ask = 'service';
else if (!hasDate || !hasTime) next_ask = 'datetime';

const stage = next_ask ? 'collecting' : 'ready';
return [{ json: { ...j, state: { ...j.state, stage }, next_ask } }];

// Answer FAQ — deterministik (LLM DEĞİL): faqTopic'e göre config'den cevap üret.
// computed_reply'ı SADECE item'a koyar; state'e/Airtable'a YAZMAZ (tek-turluk geçici çıktı).
const cfg = $('Load Config').first().json.config;
const slots = $json.slots || {};
const topic = slots.faqTopic;             // price|hours|services|address|parking|walkin|other|null
const serviceId = slots.serviceId;

const svc = cfg.services || [];
const money = (s) => s.priceEUR != null ? `€${s.priceEUR}` : 'price on request';

let answer;
switch (topic) {
  case 'price': {
    const one = serviceId ? svc.find(s => s.id === serviceId) : null;
    answer = one
      ? `${one.name} is ${money(one)}.`
      : 'Our prices: ' + svc.map(s => `${s.name} ${money(s)}`).join(', ') + '.';
    break;
  }
  case 'services':
    answer = 'We offer: ' + svc.map(s => `${s.name} (${s.durationMin} min)`).join(', ') + '.';
    break;
  case 'hours': {
    const days = ['mon','tue','wed','thu','fri','sat','sun'];
    const label = { mon:'Mon', tue:'Tue', wed:'Wed', thu:'Thu', fri:'Fri', sat:'Sat', sun:'Sun' };
    const wh = cfg.workingHours || {};
    answer = 'Opening hours — ' + days
      .map(d => `${label[d]}: ${(wh[d] && wh[d].length) ? wh[d].join(', ') : 'closed'}`)
      .join(' · ') + '.';
    break;
  }
  case 'address':
  case 'parking':
  case 'walkin':
    answer = (cfg.faq && cfg.faq[topic]) || cfg.messageTemplates.faqUnknown;
    break;
  default:  // 'other', null veya beklenmedik → dürüst deflect, ASLA tahmin
    answer = cfg.messageTemplates.faqUnknown;
}

return [{ json: { ...$json, computed_reply: answer } }];

// Build Lead State — Airtable create SONRASI: state'i (Validate Intent'ten) yeniden bağla + computed_reply=leadCaptured.
// computed_reply Airtable'a YAZILMAZ; item'da taşınır, Build Reply guard'lı referansla okur.
const vi  = $('Validate Intent').first().json;   // channel, sender_key, intent='capture_lead', state{stage,slots,turn_count,last_intent}
const cfg = $('Load Config').first().json.config;
return [{ json: {
  channel: vi.channel,
  sender_key: vi.sender_key,
  intent: vi.intent,                 // 'capture_lead' → Build Reply guard'ı için
  state: vi.state,                   // stage/slots/turn_count/last_intent='capture_lead' → Save State bunu yazar
  computed_reply: cfg.messageTemplates.leadCaptured
} }];

// Build FreeBusy Query — the requested day's UTC window (shop-tz aware, DST-correct) for freeBusy.
const cfg = $('Load Config').first().json.config;
const tz = cfg.business.timezone;
const date = $json.state.slots.date;
const dayStart = DateTime.fromISO(date, { zone: tz }).startOf('day').toUTC().toISO();
const dayEnd = DateTime.fromISO(date, { zone: tz }).endOf('day').toUTC().toISO();
return [{ json: { ...$json, freebusy: { timeMin: dayStart, timeMax: dayEnd, calId: cfg.googleCalendarId } } }];

// Compute Availability — working hours (shop tz) minus GCal busy; does the slot fit? + alternatives. UTC/DST-correct.
const cfg = $('Load Config').first().json.config;
const gate = $('Slot Gate').first().json;
const st = gate.state;
const tz = cfg.business.timezone;
const slots = st.slots;
const svc = (cfg.services || []).find(s => s.id === slots.serviceId);
const dur = svc.durationMin;
const svcName = svc.name; // Slot Gate's config allow-list guarantees svc exists here — no silent 30-min fallback (Codex root-cause pattern removed)
const start = DateTime.fromISO(slots.date + 'T' + slots.time, { zone: tz });
const end = start.plus({ minutes: dur });
const now = DateTime.now().setZone(tz);
const wdKey = ['mon','tue','wed','thu','fri','sat','sun'][start.weekday - 1];
const windows = (cfg.workingHours && cfg.workingHours[wdKey]) || [];
const wins = windows.map(w => { const p = w.split('-'); return { open: DateTime.fromISO(slots.date + 'T' + p[0], { zone: tz }), close: DateTime.fromISO(slots.date + 'T' + p[1], { zone: tz }) }; });
const cals = $json.calendars || {};
const firstCal = Object.values(cals)[0] || { busy: [] };
if (firstCal.errors && firstCal.errors.length) throw new Error('calendar_error: ' + JSON.stringify(firstCal.errors)); // fail-loud: freeBusy 200 with errors is NOT 'available'
const busy = (firstCal.busy || []).map(b => ({ s: DateTime.fromISO(b.start), e: DateTime.fromISO(b.end) }));
const overlaps = (s, e) => busy.some(b => s < b.e && b.s < e);
const withinHours = (s, e) => wins.some(w => s >= w.open && e <= w.close);
const fmt = start.toFormat('cccc d LLL HH:mm');
let stage, reply, status;
if (!slots.date || !slots.time || !start.isValid) { status = 'invalid'; stage = 'collecting'; reply = `Sorry, I couldn't read that date/time — what day and time would you like?`; }
else if (start < now) { status = 'past'; stage = 'collecting'; reply = `${fmt} has already passed — give me a future day and time.`; }
else if (wins.length === 0 || !withinHours(start, end)) { status = 'closed'; stage = 'collecting'; const hrs = windows.length ? windows.join(', ') : 'closed that day'; reply = `We're closed then — on ${start.toFormat('cccc')} we're open ${hrs}. What time works?`; }
else if (overlaps(start, end)) { status = 'busy'; stage = 'collecting'; const alts = []; for (const w of wins) { let t = w.open; while (t.plus({ minutes: dur }) <= w.close && alts.length < 3) { const te = t.plus({ minutes: dur }); if (t >= now && !overlaps(t, te)) alts.push(t.toFormat('HH:mm')); t = t.plus({ minutes: 30 }); } } reply = alts.length ? `${fmt} is taken. Free that day: ${alts.join(', ')}. Which works?` : `${fmt} is taken and that day is full — want another day?`; }
else { status = 'available'; stage = 'confirming'; reply = `${svcName}, ${fmt} — shall I book it? (yes / no)`; }
return [{ json: { ...gate, state: { ...st, stage }, availability: { status }, computed_reply: reply } }];

// Build Event Request — GCal events.insert payload from confirmed slots (shop tz + UTC, DST-correct, NO attendees).
const cfg = $('Load Config').first().json.config;
const vi = $('Validate Intent').first().json;
const st = vi.state;
const slots = st.slots;
const tz = cfg.business.timezone;
const svc = (cfg.services || []).find(s => s.id === slots.serviceId);
if (!svc) throw new Error('Build Event Request: serviceId "' + slots.serviceId + '" not in config.services — Slot Gate/Merge Slots must block invalid services (no silent 30-min fallback)'); // fail-loud, not a silent wrong booking
const dur = svc.durationMin;
const svcName = svc.name;
const name = (vi.slots && vi.slots.customerName) || null;
const start = DateTime.fromISO(slots.date + 'T' + slots.time, { zone: tz });
const end = start.plus({ minutes: dur });
const summary = svcName + (name ? ' — ' + name : '') + ' (bot)';
// CP2c-ii: deterministic GCal event id from the BOOKING KEY (sender_key|date|time|service), hex-encoded
// (valid base32hex, injective → no collisions). Same booking key → same id → a duplicate insert 409s, so a
// retry (or an insert whose response was lost) reconciles to the existing event instead of double-booking.
const bkey = [vi.sender_key, slots.date, slots.time, slots.serviceId].join('|');
if (!/^[\x00-\x7F]+$/.test(bkey)) throw new Error('Build Event Request: booking key has non-ASCII — the allow-list/senderId guard should keep it ASCII'); // Codex defense-in-depth
// UTF-8 byte encoding (NOT charCodeAt — that truncates surrogate pairs, so 😀 and 😁 would collide to the
// same id, letting a crafted sessionId reconcile onto another customer's event). TextEncoder is a global (no require).
const eventId = Array.from(new TextEncoder().encode(bkey)).map(b => b.toString(16).padStart(2, '0')).join('');
return [{ json: { ...vi, booking: { calId: cfg.googleCalendarId, timeZone: tz, startISO: start.toISO(), endISO: end.toISO(), startUTC: start.toUTC().toISO(), endUTC: end.toUTC().toISO(), summary, service: slots.serviceId, serviceName: svcName, customerName: name, dateStr: start.toFormat('cccc d LLL'), timeStr: start.toFormat('HH:mm'), eventId } } }];

// Build Booked State — GCal write OK (event id) -> booked + confirmation. gcal_event_id carried (mirror + cancel).
const cfg = $('Load Config').first().json.config;
const be = $('Build Event Request').first().json;
const b = be.booking;
const st = be.state;
const eventId = $('Build Event Request').first().json.booking.eventId || null;
const t = cfg.messageTemplates;
const reply = (t.bookingConfirmed || `You're booked: {service}, {date} {time}. See you then!`).split('{service}').join(b.serviceName).split('{date}').join(b.dateStr).split('{time}').join(b.timeStr);
return [{ json: { ...be, state: { ...st, stage: 'booked' }, gcal_event_id: eventId, computed_reply: reply, _post_write: true } }];

// Check Race — write-then-verify (booking-integrity): after our GCal insert, re-read the slot window.
// Any OTHER event overlapping our slot means we lost the concurrency race and must yield OUR event.
// events.list returns the RAW list (unlike freeBusy) — exclude cancelled + transparent ("Free") events.
const cfg = $('Load Config').first().json.config;
const tz = cfg.business.timezone;
const be = $('Build Event Request').first().json;
const b = be.booking;
const ourId = $('Build Event Request').first().json.booking.eventId;
const ourStart = new Date(b.startUTC).getTime();
const ourEnd = new Date(b.endUTC).getTime();
// Codex #3+#4: the verify read is INCOMPLETE if it was paginated (nextPageToken) OR the calendar's own
// timezone differs from the shop tz (all-day boundary math would be wrong). Fail safe: yield our event +
// mark verify_incomplete so the customer gets a NEUTRAL "couldn't confirm" message (never "just taken"),
// and never enter the happy path on an uncertain read.
const calTz = $json.timeZone;
if ($json.nextPageToken || (calTz && calTz !== tz)) {
  return [{ json: { ...be, gcal_event_id: ourId, race_lost: true, race_other_count: -1, verify_incomplete: true } }];
}
// Codex #5: all-day events carry start.date (no time) — parse at shop-tz midnight, NOT UTC midnight.
const toMs = (p) => {
  if (!p) return null;
  if (p.dateTime) return new Date(p.dateTime).getTime();
  if (p.date) return DateTime.fromISO(p.date, { zone: tz }).toMillis();
  return null;
};
const items = $json.items || [];
const overlaps = items.filter(ev => {
  if (ev.status === 'cancelled') return false;
  if (ev.transparency === 'transparent') return false;
  const s = toMs(ev.start);
  const e = toMs(ev.end);
  if (s === null || e === null) return false;
  return s < ourEnd && e > ourStart;
});
const others = overlaps.filter(ev => ev.id !== ourId);
return [{ json: { ...be, gcal_event_id: ourId, race_lost: others.length >= 1, race_other_count: others.length } }];

// Build Race-Lost State — lost the race AND successfully deleted OUR event (clean withdrawal).
// Slot yielded to the other booking; customer handed to a human. No orphan (our event is gone).
const cfg = $('Load Config').first().json.config;
const be = $('Build Event Request').first().json;
const st = be.state;
const vi = (() => { try { return $('Check Race').first().json.verify_incomplete === true; } catch (e) { return false; } })();
const reply = vi ? (cfg.messageTemplates.verifyIncomplete || 'We could not finish confirming that time just now — a team member will follow up to lock it in.') : ((cfg.messageTemplates.slotJustTaken) || 'Sorry — that time was just taken. A team member will help you find another slot.');
return [{ json: { ...be, state: { ...st, stage: 'handoff' }, race_lost: true, gcal_event_id: null, computed_reply: reply, _post_write: true } }];

// Build Orphan State — lost the race but the DELETE of our event FAILED → our event is still on the calendar.
// Visible, recoverable double-book: persist gcal_event_id so the owner can delete the stray event by hand.
const cfg = $('Load Config').first().json.config;
const be = $('Build Event Request').first().json;
const st = be.state;
const ourId = $('Build Event Request').first().json.booking.eventId;
const vi = (() => { try { return $('Check Race').first().json.verify_incomplete === true; } catch (e) { return false; } })();
const reply = vi ? (cfg.messageTemplates.verifyIncomplete || 'We could not finish confirming that time just now — a team member will follow up to lock it in.') : ((cfg.messageTemplates.slotJustTaken) || 'Sorry — that time was just taken. A team member will help you find another slot.');
return [{ json: { ...be, state: { ...st, stage: 'handoff' }, orphan_event: true, gcal_event_id: ourId, computed_reply: reply, _post_write: true } }];

// Build Verify-Unavailable State — the post-write verify READ failed (calendar unreachable).
// The event IS written. We do NOT delete on a read-failure (could cancel a legit sole booking) and we do
// NOT return 503 (a provider retry would double-book). Keep the event, hand off, flag distinctly for the owner.
const cfg = $('Load Config').first().json.config;
const be = $('Build Event Request').first().json;
const st = be.state;
const ourId = $('Build Event Request').first().json.booking.eventId;
const reply = (cfg.messageTemplates.bookingNeedsConfirm) || "Thanks! We're confirming your booking now — a team member will follow up shortly.";
return [{ json: { ...be, state: { ...st, stage: 'handoff' }, verify_unavailable: true, gcal_event_id: ourId, computed_reply: reply, _post_write: true } }];

// Build Mirror-Failed State — GCal event is written (authoritative) but the Airtable appointments MIRROR failed.
// The booking IS real, so we still confirm to the customer; but flag mirror_failed + keep gcal_event_id so the
// owner (Phase-5 alert) can repair the missing mirror row. Fail-loud on the mirror, never silent.
const cfg = $('Load Config').first().json.config;
const be = $('Build Event Request').first().json;
const b = be.booking;
const st = be.state;
const eventId = $('Build Event Request').first().json.booking.eventId || null;
const t = cfg.messageTemplates;
const reply = (t.bookingConfirmed || `You're booked: {service}, {date} {time}. See you then!`).split('{service}').join(b.serviceName).split('{date}').join(b.dateStr).split('{time}').join(b.timeStr);
return [{ json: { ...be, state: { ...st, stage: 'booked' }, mirror_failed: true, gcal_event_id: eventId, computed_reply: reply, _post_write: true } }];

// Dedupe Gate — Airtable search REPLACES the item, so re-attach the normalized payload from Normalize Inbound.
// Empty search (alwaysOutputData) yields no record id → not a duplicate; a returned record id → already processed.
const norm = $('Normalize Inbound').first().json;
const hit = !!($json && $json.id);
return [{ json: { ...norm, _duplicate: hit } }];

// Verify Reconcile — CP2c-ii: a duplicate-insert 409 (or a reconciled ambiguous failure) is idempotent ONLY if
// the existing event with our deterministic id is LIVE (status != cancelled) AND covers our EXACT slot. A
// race-lost delete leaves the id reserved as a cancelled tombstone → an unverified 409 would falsely report
// "booked". Reconstruct context via node refs; compare times by epoch (Google omits milliseconds).
const be = $('Build Event Request').first().json;
const b = be.booking;
const ev = $json;
const ourStart = new Date(b.startUTC).getTime();
const ourEnd = new Date(b.endUTC).getTime();
const evStart = ev.start && ev.start.dateTime ? new Date(ev.start.dateTime).getTime() : null;
const evEnd = ev.end && ev.end.dateTime ? new Date(ev.end.dateTime).getTime() : null;
const ok = ev.status !== 'cancelled' && evStart === ourStart && evEnd === ourEnd;
return [{ json: { ...be, _reconcile_ok: ok } }];

// Build Reconcile-Handoff State — the deterministic event id exists but as a CANCELLED tombstone (a prior
// booking for this exact slot was deleted, e.g. a CP2b race-loss). We cannot reuse the id and made no new
// booking → hand off. Context rebuilt via node refs (this is an error/branch path — the incoming item is the
// GCal event, not our state).
const be = $('Build Event Request').first().json;
const st = be.state;
return [{ json: { ...be, state: { ...st, stage: 'handoff' }, reconcile_conflict: true } }];

// Classify Reconcile Failure — Codex #1: the reconcile GET failed. A DEFINITE 404 means the event was never
// created → safe to 503 (a retry is safe; nothing exists). Any other failure (timeout / transport / 5xx) is
// UNRESOLVED: the event MIGHT exist, so we must NOT 503 (retry loop) → 200 handoff with the id visible.
// Reconstruct context via node refs (the error item carries only the error, not our fields).
const be = $('Build Event Request').first().json;
const err = ($json && $json.error) || $json || {};
const code = String(err.httpCode || err.code || (err.context && err.context.httpCode) || '');
const msg = String(err.message || '');
const notFound = code === '404' || /not found|404/i.test(msg);
return [{ json: { ...be, _reconcile_404: notFound } }];

// Build Reconcile-Unresolved State — the reconcile GET was UNRESOLVED (timeout / transport / 5xx); we cannot
// confirm whether the event exists. Do NOT 503 (a retry loops — the deterministic id makes a 2nd insert 409,
// not a double-book, but we still avoid the loop). Hand off with the id visible so the owner can reconcile.
const cfg = $('Load Config').first().json.config;
const be = $('Build Event Request').first().json;
const st = be.state;
const eventId = be.booking.eventId;
const reply = (cfg.messageTemplates.bookingNeedsConfirm) || "Thanks! We're confirming your booking now — a team member will follow up shortly.";
return [{ json: { ...be, state: { ...st, stage: 'handoff' }, reconcile_unresolved: true, gcal_event_id: eventId, computed_reply: reply, _post_write: true } }];

// Cancel Lookup — ASK: pick the sender's OWN next-upcoming booked appt (IDOR-safe: Find Booking filtered by
// sender_key), run the FULL structural validation (Codex#8 LOW-2: never build a confirm prompt on a broken row)
// and decide confirm/none/cutoff/needs_human. EXECUTE ("yes"): bind to the EXACT record confirmed last turn
// (state.cancel_target_id) — NEVER re-pick booked[0]. If that bound row is no longer booked → target_gone (Codex#8
// LOW-3: a NEUTRAL message, never "I found your booking"). The delete-time gate is 'Validate Cancel Target'.
const cfg = $('Load Config').first().json.config;
const vi = $('Validate Intent').first().json;
const st = vi.state;
const now = Date.now();
const cutoffMs = (cfg.bot.cancellationCutoffHours || 0) * 3600 * 1000;
const mode = (vi.intent === 'confirm' && st.stage === 'cancel_confirming') ? 'execute' : 'ask';
const rows = $input.all().map(i => i.json).filter(r => r && r.id && r.fields);
const booked = rows.filter(r => r.fields.status === 'booked' && r.fields.start_utc)
  .sort((a, b) => new Date(a.fields.start_utc) - new Date(b.fields.start_utc));
const mk = (t) => ({ recordId: t.id, gcal_event_id: t.fields.gcal_event_id, calendar_id: t.fields.calendar_id, service: t.fields.service, start_utc: t.fields.start_utc });
const structOk = (t) => {
  const gid = (t.fields.gcal_event_id || '').trim();
  const cal = (t.fields.calendar_id || '').trim();
  return Number.isFinite(new Date(t.fields.start_utc).getTime()) && /^[0-9a-v]{5,1024}$/.test(gid) && cal.length > 0;
};
let outcome, target = null, gone = false;
if (mode === 'execute') {
  const t = booked.find(r => r.id === st.cancel_target_id) || null;
  if (!t) { outcome = 'needs_human'; gone = true; }   // bound row no longer booked → neutral message, never guess
  else { outcome = 'execute'; target = mk(t); }
} else if (booked.length === 0) {
  outcome = 'none';
} else {
  const t = booked[0];
  if (!structOk(t)) outcome = 'needs_human';          // LOW-2: broken row → needs-human BEFORE any confirm prompt
  else if (new Date(t.fields.start_utc).getTime() - now < cutoffMs) outcome = 'cutoff';
  else { outcome = 'confirm'; target = mk(t); }
}
const route = outcome;   // confirm / execute / none / cutoff / needs_human
return [{ json: { ...vi, _cancel_route: route, _cancel_target: target, _cancel_count: booked.length, _cancel_target_gone: gone } }];

// Build Cancel-Confirm State — confirm-before-delete: name the appointment (honesty), note multiple bookings.
// stage=cancel_confirming; persist the confirmed record id (cancel_target_id) so 'yes' binds to THIS exact
// booking, plus confirm_turn = turn_count+1 so the confirm is only honored on the immediate next turn (TTL).
const cfg = $('Load Config').first().json.config;
const j = $json;
const t = j._cancel_target;
const tz = cfg.business.timezone;
const when = DateTime.fromISO(t.start_utc, { zone: 'utc' }).setZone(tz).toFormat('cccc d LLL HH:mm');
const multi = j._cancel_count > 1 ? ` (you have ${j._cancel_count} bookings — this cancels the ${when} one)` : '';
const reply = `Cancel your ${t.service} on ${when}?${multi} Reply "yes" to cancel, or anything else to keep it.`;
return [{ json: { ...j, state: { ...j.state, stage: 'cancel_confirming', cancel_target_id: t.recordId, confirm_turn: String(j.state.turn_count + 1) }, computed_reply: reply } }];

// Build No-Booking Reply — the sender has no active booking to cancel (informational, no state change).
const cfg = $('Load Config').first().json.config;
return [{ json: { ...$json, computed_reply: (cfg.messageTemplates.cancelNoBooking || 'You have no active booking to cancel.') } }];

// Build Cancel-Cutoff Reply — booking is within cancellationCutoffHours of its time → bot won't cancel; hand off.
const cfg = $('Load Config').first().json.config;
return [{ json: { ...$json, state: { ...$json.state, stage: 'handoff' }, computed_reply: (cfg.messageTemplates.cancelCutoff || 'That booking is too close to its time to cancel here — please call us.') } }];

// Build Cancel-NeedsHuman State — cannot safely delete. If the bound target vanished between confirm and "yes"
// (_cancel_target_gone) → a NEUTRAL message (Codex#8 LOW-3: never falsely say "I found your booking"); otherwise
// the row exists but is unsafe to auto-cancel → the found-but-cannot message. Never guess an event id.
const cfg = $('Load Config').first().json.config;
const gone = !!$json._cancel_target_gone;
const reply = gone
  ? (cfg.messageTemplates.cancelTargetGone || "I couldn't find that booking to cancel anymore — a team member will follow up shortly.")
  : (cfg.messageTemplates.cancelNeedsHuman || "I found your booking but can't cancel it automatically — a team member will cancel it for you.");
return [{ json: { ...$json, state: { ...$json.state, stage: 'handoff' }, cancel_needs_human: true, computed_reply: reply } }];

// Classify Cancel Delete — STRUCTURAL only (Codex #8): Delete Booking Event runs fullResponse+neverError, so any
// HTTP response (incl. 4xx/5xx) reaches the success output carrying $json.statusCode, and only a transport error
// (timeout/DNS) reaches the error output as $json.error. 204/200 = deleted; 404/410 = already gone (idempotent);
// anything else (5xx / transport) = UNAVAILABLE — the event may still exist, so NEVER tell the customer 'cancelled'.
// Never inspect the error TEXT: 'host not found' must not be misread as 'booking not found'.
const cl = $('Validate Cancel Target').first().json;
const err = ($json && $json.error) || null;
let outcome;
if (err) outcome = 'unavailable';
else {
  const sc = Number($json.statusCode);
  if (sc === 204 || sc === 200) outcome = 'deleted';
  else if (sc === 404 || sc === 410) outcome = 'gone';
  else outcome = 'unavailable';
}
return [{ json: { ...cl, _cancel_delete: outcome } }];

// Build Cancelled State — GCal event deleted (or already gone) -> booking cancelled. If the Airtable mirror update
// failed, still confirm (GCal is source of truth) but flag it. Reconstruct via node refs.
const cfg = $('Load Config').first().json.config;
const t = $('Validate Cancel Target').first().json._cancel_target;
const del = $('Classify Cancel Delete').first().json._cancel_delete;
const vi = $('Validate Intent').first().json;
const st = vi.state;
const tz = cfg.business.timezone;
const when = DateTime.fromISO(t.start_utc, { zone: 'utc' }).setZone(tz).toFormat('cccc d LLL HH:mm');
const mirrorFail = !!($json && $json.error);
const tmpl = del === 'gone' ? (cfg.messageTemplates.cancelAlreadyDone || 'That booking is already cancelled.') : (cfg.messageTemplates.cancelDone || 'Done — your {service} on {when} is cancelled.');
const reply = tmpl.split('{service}').join(t.service).split('{when}').join(when);
return [{ json: { ...vi, state: { ...st, stage: 'cancelled' }, cancel_mirror_failed: mirrorFail, gcal_event_id: t.gcal_event_id, computed_reply: reply, _post_write: true } }];

// Validate Cancel Target — the structural safety gate BEFORE any delete (Codex #8). Re-validate the bound target:
// start_utc must be a real time (NaN must NOT pass the cutoff check open), still OUTSIDE the cancellation cutoff,
// the gcal_event_id must match the stored id shape, and calendar_id must be present (pre-CP3 rows have none). Any
// failure -> _cancel_valid=false -> never delete -> needs_human. Closes Codex #8: NaN-start, blank/short event id,
// missing calendar_id, and confirm/execute target-binding (the id itself is bound in Cancel Lookup).
const cfg = $('Load Config').first().json.config;
const now = Date.now();
const cutoffMs = (cfg.bot.cancellationCutoffHours || 0) * 3600 * 1000;
const t = $json._cancel_target || {};
const gid = (t.gcal_event_id || '').trim();
const cal = (t.calendar_id || '').trim();
const startMs = new Date(t.start_utc).getTime();
const valid = Number.isFinite(startMs) && (startMs - now >= cutoffMs)
  && /^[0-9a-v]{5,1024}$/.test(gid) && cal.length > 0;
return [{ json: { ...$json, _cancel_valid: valid, _cancel_target: { ...t, gcal_event_id: gid, calendar_id: cal } } }];

// Build Cancel-Aborted State — the pending cancel confirmation is dropped: either a non-confirm intent arrived
// while awaiting "yes" (Codex#8 fix#2), or the confirmation went stale via an intervening turn (Codex#8 HIGH, TTL
// fail-closed). Clear the confirm state (stage + target + confirm_turn) and tell the customer their booking stands.
const cfg = $('Load Config').first().json.config;
const vi = $('Validate Intent').first().json;
const st = vi.state;
return [{ json: { ...vi, state: { ...st, stage: 'new', cancel_target_id: '', confirm_turn: '' }, computed_reply: (cfg.messageTemplates.cancelAborted || 'No problem — your booking stands.') } }];

// Verify Confirm Live — HIGH mitigation (Codex PART-B re-audit): re-read the conversation IMMEDIATELY before the
// DELETE and re-check the confirmation is still live (stage=cancel_confirming AND confirm_turn unchanged & canonical).
// A concurrent turn that already consumed the confirm changed the stage/turn -> _confirm_live=false -> NO delete.
// NOT atomic (narrows the race from the whole execution to two nodes); the full fix = per-sender serialization /
// atomic compare-and-consume across the whole state model = Phase 5, not a CP3 patch.
const vct = $('Validate Cancel Target').first().json;   // carries _cancel_target for the delete URL
const turnCt = $('Validate Intent').first().json.state.confirm_turn;
const rows = $input.all().map(i => i.json).filter(r => r && r.id && r.fields);
const rer = rows[0] || null;
const live = !!(rer && rer.fields.stage === 'cancel_confirming' && typeof turnCt === 'string' && /^[1-9][0-9]*$/.test(turnCt) && rer.fields.confirm_turn === turnCt);
return [{ json: { ...vct, _confirm_live: live } }];
